import { ethers } from 'ethers'

import {
  setProvider,
  setNetwork,
  setAccount
} from './reducers/provider'

import {
  setContracts,
  setSymbols,
  balancesLoaded
} from './reducers/tokens'

import {
  setContract,
  sharesLoaded,
  swapsLoaded,
  depositRequest,
  depositSuccess,
  depositFail,
  withdrawRequest,
  withdrawSuccess,
  withdrawFail,
  swapRequest,
  swapSuccess,
  swapFail
} from './reducers/amm'

import {
  setCrowdsaleContract,
  setSaleStatus,
  setCrowdsaleStats,
  setUserContribution,
  buyTokensRequest,
  buyTokensSuccess,
  buyTokensFail
} from './reducers/crowdsale'

import TOKEN_ABI from '../abis/Token.json';
import AMM_ABI from '../abis/AMM.json';
import CROWDSALE_ABI from '../abis/Crowdsale.json';
import config from '../config.json';

export const loadProvider = (dispatch) => {
  const provider = new ethers.providers.Web3Provider(window.ethereum)
  dispatch(setProvider(provider))

  return provider
}

export const loadNetwork = async (provider, dispatch) => {
  const { chainId } = await provider.getNetwork()
  dispatch(setNetwork(chainId))

  return chainId
}

export const loadAccount = async (dispatch) => {
  const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' })
  const account = ethers.utils.getAddress(accounts[0])
  dispatch(setAccount(account))

  return account
}

// ------------------------------------------------------------------------------
// LOAD CONTRACTS
export const loadTokens = async (provider, chainId, dispatch) => {
  const dapp = new ethers.Contract(config[chainId].dapp.address, TOKEN_ABI, provider)
  const usd = new ethers.Contract(config[chainId].usd.address, TOKEN_ABI, provider)

  dispatch(setContracts([dapp, usd]))
  dispatch(setSymbols([await dapp.symbol(), await usd.symbol()]))
}

export const loadAMM = async (provider, chainId, dispatch) => {
  const amm = new ethers.Contract(config[chainId].amm.address, AMM_ABI, provider)

  dispatch(setContract(amm))

  return amm
}


// ------------------------------------------------------------------------------
// LOAD BALANCES & SHARES
export const loadBalances = async (amm, tokens, account, dispatch) => {
  const balance1 = await tokens[0].balanceOf(account)
  const balance2 = await tokens[1].balanceOf(account)

  dispatch(balancesLoaded([
    ethers.utils.formatUnits(balance1.toString(), 'ether'),
    ethers.utils.formatUnits(balance2.toString(), 'ether')
  ]))

  const shares = await amm.shares(account)
  dispatch(sharesLoaded(ethers.utils.formatUnits(shares.toString(), 'ether')))
}


// ------------------------------------------------------------------------------
// ADD LIQUDITY
export const addLiquidity = async (provider, amm, tokens, amounts, dispatch) => {
  try {
    dispatch(depositRequest())

    const signer = await provider.getSigner()

    let transaction

    transaction = await tokens[0].connect(signer).approve(amm.address, amounts[0])
    await transaction.wait()

    transaction = await tokens[1].connect(signer).approve(amm.address, amounts[1])
    await transaction.wait()

    transaction = await amm.connect(signer).addLiquidity(amounts[0], amounts[1])
    await transaction.wait()

    dispatch(depositSuccess(transaction.hash))
  } catch (error) {
    dispatch(depositFail())
  }
}

// ------------------------------------------------------------------------------
// REMOVE LIQUDITY
export const removeLiquidity = async (provider, amm, shares, dispatch) => {
  try {
    dispatch(withdrawRequest())

    const signer = await provider.getSigner()

    let transaction = await amm.connect(signer).removeLiquidity(shares)
    await transaction.wait()

    dispatch(withdrawSuccess(transaction.hash))
  } catch (error) {
    dispatch(withdrawFail())
  }
}

// ------------------------------------------------------------------------------
// SWAP

export const swap = async (provider, amm, token, symbol, amount, dispatch) => {
  try {

    dispatch(swapRequest())

    let transaction

    const signer = await provider.getSigner()

    transaction = await token.connect(signer).approve(amm.address, amount)
    await transaction.wait()

    if (symbol === "DAPP") {
      transaction = await amm.connect(signer).swapToken1(amount)
    } else {
      transaction = await amm.connect(signer).swapToken2(amount)
    }

    await transaction.wait()

    dispatch(swapSuccess(transaction.hash))

    return transaction

  } catch (error) {
    dispatch(swapFail())
  }
}


// ------------------------------------------------------------------------------
// LOAD ALL SWAPS

export const loadAllSwaps = async (provider, amm, dispatch) => {
  const block = await provider.getBlockNumber()

  const swapStream = await amm.queryFilter('Swap', 0, block)
  const swaps = swapStream.map(event => {
    return { hash: event.transactionHash, args: event.args }
  })

  dispatch(swapsLoaded(swaps))
}

// ------------------------------------------------------------------------------
// CROWDSALE INTERACTIONS

export const loadCrowdsale = async (provider, chainId, dispatch) => {
  const crowdsale = new ethers.Contract(
    config[chainId].crowdsale.address,
    CROWDSALE_ABI,
    provider
  )

  dispatch(setCrowdsaleContract(crowdsale))

  return crowdsale
}

export const loadCrowdsaleStatus = async (crowdsale, dispatch) => {
  try {
    const isOpen = await crowdsale.isOpen()
    const whitelistEnabled = await crowdsale.whitelistEnabled()

    dispatch(setSaleStatus({
      isPaused: !isOpen,
      isOpen: isOpen,
      whitelistEnabled: whitelistEnabled
    }))

    return { isOpen, whitelistEnabled }
  } catch (error) {
    console.error('Error loading crowdsale status:', error)
    return null
  }
}

export const loadCrowdsaleStats = async (crowdsale, dispatch) => {
  try {
    const tokensSold = await crowdsale.tokensSold()
    const price = await crowdsale.price()

    // Calculate total ETH raised: tokensSold * price
    const totalRaised = tokensSold.mul(price).div(ethers.utils.parseEther('1'))

    dispatch(setCrowdsaleStats({
      totalRaised: totalRaised.toString(),
      totalTokensSold: tokensSold.toString()
    }))

    return { totalRaised, tokensSold }
  } catch (error) {
    console.error('Error loading crowdsale stats:', error)
    return null
  }
}

export const checkWhitelist = async (crowdsale, account, dispatch) => {
  try {
    const isWhitelisted = await crowdsale.whitelist(account)

    dispatch(setUserContribution({
      isWhitelisted: isWhitelisted
    }))

    return isWhitelisted
  } catch (error) {
    console.error('Error checking whitelist:', error)
    return false
  }
}

export const loadUserContribution = async (crowdsale, account, dispatch) => {
  try {
    // Note: The contract doesn't track individual contributions
    // We can only check if they're whitelisted
    const isWhitelisted = await crowdsale.whitelist(account)

    dispatch(setUserContribution({
      amount: '0', // Contract doesn't track this
      isWhitelisted: isWhitelisted
    }))

    return { isWhitelisted }
  } catch (error) {
    console.error('Error loading user contribution:', error)
    return null
  }
}

export const buyTokens = async (provider, crowdsale, ethAmount, dispatch) => {
  try {
    dispatch(buyTokensRequest())

    const signer = await provider.getSigner()

    // Get price and calculate token amount
    const price = await crowdsale.price()
    const ethValue = ethers.utils.parseEther(ethAmount.toString())

    // Calculate how many tokens for this ETH amount
    // tokenAmount = (ethValue * 1e18) / price
    const tokenAmount = ethValue.mul(ethers.utils.parseEther('1')).div(price)

    const transaction = await crowdsale.connect(signer).buyTokens(tokenAmount, { value: ethValue })
    await transaction.wait()

    dispatch(buyTokensSuccess(transaction.hash))

    return transaction
  } catch (error) {
    console.error('Error buying tokens:', error)
    dispatch(buyTokensFail())
    throw error
  }
}

